\begin{gathered}
\left.\therefore F=\frac{\left(\epsilon_0 A V^2\right)}{\mathrm{d}^2 \times 2 \mathrm{~A} \epsilon_0}\right) \\
=\frac{\left(\epsilon_0 A\right)^2 \times V^2}{d^2 \times 2 \times\left(A \epsilon_0\right)}=\frac{\left(\epsilon_0 A\right) \times V^2}{d^2 \times 2} \\
\text { or, } 25 \times 10^{-6}=\frac{\left(8.85 \times 10^{-12}\right) \times\left(200 \times 10^{-4}\right) \times V^2}{2.25 \times 10^{-4} \times 2} \\
\Rightarrow V=\frac{25 \times 10^{-6} \times 2.25 \times 10^{-4} \times 2}{8.85 \times 10^{-12} \times 200 \times 10^{-4}} \approx 250 \mathrm{~V}
\end{gathered}

The value of dielectric constant is given as,

\begin{aligned}
&\mathrm{K}=\mathrm{K}_0+\lambda \mathrm{x} \\
&\text { And, } \mathrm{V}=\int_0^{\mathrm{d}} \mathrm{Edr} \\
&\mathrm{V}=\int_0^{\mathrm{d}} \frac{\sigma}{\mathrm{K}} \mathrm{dx}
\end{aligned}

\begin{aligned}
&=\sigma \int_0^{\mathrm{d}} \frac{1}{\left(\mathrm{~K}_0+\lambda \mathrm{x}\right.} \mathrm{dx} \\
&=\frac{\sigma}{\lambda}\left[\ln \left(\mathrm{K}_0+\lambda \mathrm{d}-\ln \mathrm{K}_0\right]\right. \\
&=\frac{\sigma}{\lambda} \ln \left(1+\frac{\lambda \mathrm{d}}{\mathrm{K}_0}\right)
\end{aligned}

Now it is given that capacitance of vacuum $=\mathrm{C}_0$.
Thus, $\mathrm{C}=\frac{\mathrm{Q}}{\mathrm{V}}$
\begin{aligned}
&=\frac{\sigma . \mathrm{s}}{\mathrm{v}}(\text { Let surface area of plates }=\mathrm{s}) \\
&=\frac{\sigma . \mathrm{s}}{\frac{\sigma}{\lambda} \ln \left(1+\frac{\lambda \mathrm{d}}{\mathrm{K}_0}\right)}
\end{aligned}

$=\mathrm{s} \lambda \cdot \frac{\mathrm{d}}{\mathrm{d}} \frac{1}{\ln \left(1+\frac{\lambda \mathrm{d}}{\mathrm{K}_0}\right)}\left(\because\right.$ in vacuum $\left.\varepsilon_0=1\right)\mathrm{c}=\frac{\lambda \mathrm{d}}{\ln \left(1+\frac{\lambda \mathrm{d}}{\mathrm{K}_0}\right)} \cdot \mathrm{C}_0 \quad\left(\right.$ here, $\left.\mathrm{C}_0=\frac{\mathrm{s}}{\mathrm{d}}\right)$

As, C $=\frac{\mathrm{Q}}{\mathrm{V}}=\frac{\mathrm{It}}{\mathrm{V}}$
\begin{aligned}
& \Rightarrow \frac{\mathrm{V}}{\mathrm{t}}=\frac{\mathrm{I}}{\mathrm{C}}=\frac{2}{1 \times 10^{-6}} \\
& =2 \times 10^6 \mathrm{~V} / \mathrm{s}
\end{aligned}

\begin{aligned}
& C^{\prime}=\frac{A \varepsilon_0}{\frac{d_1}{3}+\frac{d_2}{6}}=\frac{A \varepsilon_0}{\frac{d}{9}+\frac{2 d}{18}}=\frac{18 A \varepsilon_0}{4 d} \\
& C^{\prime}=40.5 \mathrm{PF}
\end{aligned}

